/**
 * Water and wastewater framework generator (BNI method).
 *
 * Reads EPA's WCAT 3.1 checklist, CISA's CPG 1.0.1 component listing, BNI's crosswalk to
 * CPG 2.0 and the tagged CISA tabletop questions from ./inputs and writes Comp AI
 * framework-editor seed files suffixed `.water.json`. The framework borrows the CPG 2.0
 * control and evidence-task templates generated by ../cset (run that generator first).
 *
 *   bun packages/db/prisma/seed/sources/water/index.ts
 */
import { writeFileSync } from 'node:fs';
import path from 'node:path';
import { readUpstreamIds, writeOutputs, type VersionEntry } from '../nist-800-171/write';
import { build } from './build';
import { readCpg2Goals, readCpgPractices, readCrosswalk, readInterviewQuestions, readWcat } from './read';
import type { GeneratedData } from './types';
import { validate } from './validate';

const HERE = __dirname;
const INPUTS = path.join(HERE, 'inputs');
const SEED_DIR = path.resolve(HERE, '..', '..');
export const SUFFIX = 'water';

function main(): void {
  const b = build({
    wcat: readWcat(path.join(INPUTS, 'wcat-3.1.json')),
    practices: readCpgPractices(path.join(INPUTS, 'cpg-1.0.1-components.json')),
    crosswalk: readCrosswalk(path.join(INPUTS, 'wcat-to-cpg2.csv')),
    interview: readInterviewQuestions(path.join(INPUTS, 'interview-questions.csv')),
    goals: readCpg2Goals(path.join(HERE, '..', 'cset', 'inputs', 'cset-cpg2.json')),
  });

  const data: GeneratedData = {
    families: [b.family],
    frameworks: [b.framework],
    requirements: b.requirements,
    controls: [],
    policies: b.policies,
    tasks: b.tasks,
    policyLinks: b.policyLinks,
    taskLinks: b.taskLinks,
    controlRequirementPairs: b.controlRequirementPairs,
    controlPolicyPairs: b.controlPolicyPairs,
    controlTaskPairs: b.controlTaskPairs,
  };
  const summary = validate(data, b, readUpstreamIds(SEED_DIR, SUFFIX));

  const versions: VersionEntry[] = [
    {
      frameworkId: b.framework.id,
      version: '1.0.0',
      releaseNotes:
        `Initial ${b.framework.name} release: ${b.requirements.length} EPA checklist questions on ${b.borrowedControlIds.length} ` +
        `CPG 2.0 goals, ${b.policies.length} plan documents, ${b.tasks.length} interview evidence tasks.`,
    },
  ];
  const written = writeOutputs(SEED_DIR, data, versions, SUFFIX);
  const { module: _module, ...profileRow } = b.profile;
  const profilesFile = path.join(SEED_DIR, 'primitives', `FrameworkAnswerProfile.${SUFFIX}.json`);
  writeFileSync(profilesFile, `${JSON.stringify([profileRow], null, 2)}\n`);
  written.push(profilesFile);
  console.log(summary);
  console.log(`wrote ${written.length} files:`);
  for (const f of written) console.log(`  ${path.relative(SEED_DIR, f)}`);
}

main();
